from collections import deque, Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r,c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            comp = []
            while q:
                x,y = q.popleft()
                comp.append((x,y))
                for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                    if 0 <= a < h and 0 <= b < w and grid[a][b] == bg and (a,b) not in seen:
                        seen.add((a,b)); q.append((a,b))
            comps.append(comp)
    out = [row[:] for row in grid]
    if comps:
        exterior = max(comps, key=len)
        for comp in comps:
            if comp is not exterior:
                for r,c in comp:
                    out[r][c] = 4
    return out
